import{_ as t}from"./chunks/theme-light.B_WK5zUn.js";import{_ as o,o as a,c as d,a3 as n}from"./chunks/framework.BZRC44LV.js";const g=JSON.parse('{"title":"Writing in Blank","description":"","frontmatter":{},"headers":[],"relativePath":"guide/writing.md","filePath":"guide/writing.md"}'),r={name:"guide/writing.md"};function s(i,e,c,h,l,p){return a(),d("div",null,[...e[0]||(e[0]=[n('<h1 id="writing-in-blank" tabindex="-1">Writing in Blank <a class="header-anchor" href="#writing-in-blank" aria-label="Permalink to &quot;Writing in Blank&quot;">​</a></h1><p>Blank shows your text as it will look, not as markdown syntax, and on the lines and pages it will have on paper (see <a href="./pages#on-the-screen">Pages</a>). There are no toolbars: you format with <a href="./shortcuts">keyboard shortcuts</a> or by typing markdown, which Blank turns into formatting as you go.</p><img class="shot" src="'+t+'" alt="A document in Blank&#39;s light theme"><h2 id="format-as-you-type" tabindex="-1">Format as you type <a class="header-anchor" href="#format-as-you-type" aria-label="Permalink to &quot;Format as you type&quot;">​</a></h2><p>At the start of an empty line, type one of these to turn the line into a block:</p><table tabindex="0"><thead><tr><th>Type at the start of a line</th><th>Then</th><th>You get</th></tr></thead><tbody><tr><td><code>#</code> … <code>######</code></td><td>Space</td><td>Heading 1–6</td></tr><tr><td><code>-</code> <code>*</code> <code>+</code></td><td>Space</td><td>Bullet list</td></tr><tr><td><code>1.</code> (any number)</td><td>Space</td><td>Numbered list</td></tr><tr><td><code>&gt;</code></td><td>Space</td><td>Blockquote</td></tr><tr><td><code>---</code> <code>***</code> <code>___</code></td><td>Enter</td><td>Horizontal line</td></tr><tr><td><code>+++</code></td><td>Enter</td><td><a href="./pages#page-breaks">Page break</a></td></tr><tr><td><code>```</code> or <code>```lang</code></td><td>Enter</td><td>Code block</td></tr><tr><td><code>| Name | Qty |</code></td><td>Enter</td><td>Table</td></tr></tbody></table><p>Changed your mind? <code>Mod</code> <code>Z</code> right away gives you back the line as you typed it.</p><p>Inline markdown works too: <code>**bold**</code>, <code>*italic*</code>, <code>`code`</code>, <code>[title](url)</code> and plain URLs become formatting once you finish the word. See <a href="./autocorrect">Autocorrect</a> for everything Blank corrects.</p><p>Code is set in IBM Plex Mono. <code>Mod</code> + Click on a link opens it in your browser. Emoji appear in black and white, in the colour of your text. Chinese, Japanese, Korean and other scripts use the fonts your computer has for them. Whatever you write, it looks on paper just as it does on the screen, and a word too long for its line, like a long web address, simply carries on to the next one.</p><h2 id="code" tabindex="-1">Code blocks <a class="header-anchor" href="#code" aria-label="Permalink to &quot;Code blocks {#code}&quot;">​</a></h2><p>Type <code>```</code> and Enter at the start of a line to start a code block. In it, <code>Tab</code> and <code>Shift</code> <code>Tab</code> work as in a code editor: select some lines and <code>Tab</code> indents all of them by 4 spaces, <code>Shift</code> <code>Tab</code> outdents them, and the same lines stay selected, so you can press again to go further. Each line moves to the next or the previous step of 4, so a line indented by 6 spaces outdents to 4, not 2, and lines without indentation stay where they are. Without a selection, <code>Tab</code> puts in spaces up to the next step, and <code>Shift</code> <code>Tab</code> outdents the line the cursor is on. Code indented with tabs keeps its tabs. Each press is one step for <code>Mod</code> <code>Z</code>. Prefer 2 spaces? Set it in <a href="./configuration#code-blocks">blank.json</a>.</p><h2 id="tables" tabindex="-1">Tables <a class="header-anchor" href="#tables" aria-label="Permalink to &quot;Tables&quot;">​</a></h2><p>Press <code>Mod</code> <code>T</code>, pick a size with the arrow keys and press Enter. <code>Tab</code> takes you from cell to cell and adds a row at the end. <a href="./tables">Tables</a> has everything about making, filling and saving them.</p><h2 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h2><p>Press <code>Mod</code> <code>Alt</code> <code>I</code> to add an image where the cursor is. In the dialog, press <em>Choose file…</em> (Tab gets you there) to pick a picture from your computer, give it a short description and press Enter. Blank puts the picture into the document itself, so your markdown file stays a single file you can move, copy and send without losing images. Large pictures are scaled down to a size that still prints well.</p><p>Instead of choosing a file, you can also type an address into the dialog, or type <code>![description](address)</code> and a space right in the text:</p><ul><li>a web address, like <code>https://example.com/map.png</code>,</li><li>a file next to your document, like <code>images/chart.png</code>, which appears once the document has been saved, since Blank needs to know its folder,</li><li>any file on your computer, like <code>/home/me/logo.png</code>.</li></ul><p>These images stay where they are and the document links to them.</p><p>To change or remove an image, put the cursor right before or after it and press <code>Mod</code> <code>Alt</code> <code>I</code> again.</p><p>Images are as wide as they are in the file, up to the width of the page, and <a href="./files#pdf">PDFs and Word documents</a> include them at that size.</p><h2 id="blank-remembers-your-document" tabindex="-1">Blank remembers your document <a class="header-anchor" href="#blank-remembers-your-document" aria-label="Permalink to &quot;Blank remembers your document&quot;">​</a></h2><p>Blank keeps what you write as you go, at least once a second and once more when you close the window, and restores it on the next start, together with the open file, the theme and the language. So you can close the window mid-thought without saving, and pick up right where you left off.</p><h2 id="save-open-and-export" tabindex="-1">Save, open and export <a class="header-anchor" href="#save-open-and-export" aria-label="Permalink to &quot;Save, open and export&quot;">​</a></h2><p>Your documents are plain markdown files: <code>Mod</code> <code>S</code> saves, <code>Mod</code> <code>O</code> opens, also Word documents. To share a piece, export it as a PDF with <code>Mod</code> <code>Alt</code> <code>P</code> or as a Word document with <code>Mod</code> <code>Alt</code> <code>W</code>. <a href="./files">Files &amp; formats</a> has everything about PDF and Word.</p><h2 id="the-status-bar" tabindex="-1">The status bar <a class="header-anchor" href="#the-status-bar" aria-label="Permalink to &quot;The status bar&quot;">​</a></h2><p>The top of the window shows the open file, <em>Untitled</em>, or the <a href="./files#open-word-documents">Word document</a> an untitled document was imported from. The bottom shows the word and character count, <a href="./spelling">spell check</a> while it is on, and the <a href="./autocorrect#language">language</a>.</p>',26)])])}const f=o(r,[["render",s]]);export{g as __pageData,f as default};
